    [6406]={name="Nightsky Boots",quality=2,ilvl=34,reqLevel=29,sourceType="world_drop",instructions="World drop around level 27-36.",zone="Stranglethorn Vale"},
    [6407]={name="Nightsky Wristbands",quality=2,ilvl=33,reqLevel=28,sourceType="world_drop",instructions="World drop around level 26-34.",zone="Stranglethorn Vale"},
    [6414]={name="Seal of Sylvanas",quality=3,ilvl=29,reqLevel=18,sourceType="quest_reward",instructions="Reward from the quest 'Arugal Must Die'.",zone="Shadowfang Keep",questName="Arugal Must Die",lore="Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain. I shall see to it that his magic is eradicated."},
    [6418]={name="Aurora Sash",quality=2,ilvl=37,reqLevel=32,sourceType="world_drop",instructions="World drop around level 32-39.",zone="Stranglethorn Vale"},
